INSERT INTO ai_tools (name, type, description, link, "phaseIds", owner, "comingSoon") VALUES
  ('Gold Scale Strategic Coaching Agent', 'Agent', 'Strategic coaching support for Gold Scale meeting prep. Not yet available.', '#', '{"meeting-prep"}', NULL, true),
  ('Transcript to Meeting Summary Gem', 'Gem', 'Extracts key insights from client transcripts to create structured CRM notes. Focuses on CTA outcomes, Gold Status resource adoption, and Identity Maturity updates.', 'https://gemini.google.com/gem/1QpWK_no5rBle0LhM0gfLlq9Ok-k-AJaI?usp=sharing', '{"post-meeting"}', NULL, false),
  ('Transcript to CTA Update Gem', 'Gem', 'Converts a meeting transcript into a structured CTA update.', 'https://gemini.google.com/gem/1jnIKpHNPx5ymYJJVcmxD9dMDXVRYOK1O?usp=sharing', '{"post-meeting"}', NULL, false),
  ('Transcript to Security Essential', 'Gem', 'Acts as a specialized CSM/technical analyst, converting meeting transcripts into updates keyed off specific product keywords (e.g. FastPass, Workflows, LCM). Useful for follow-up emails and as a personal notetaker so a CSM doesn’t have to rewatch their own call.', 'https://gemini.google.com/gem/443cff2a10c1?usp=sharing', '{"post-meeting"}', NULL, false),
  ('Transcript to Followup Email Gem', 'Gem', 'Generates a customer-specific follow-up email from a meeting transcript and the main priority item discussed on the call.', 'https://gemini.google.com/gem/1ZCTmoW_hTA3uggWSl5Gsc_vVLRAR0jxT?usp=sharing', '{"post-meeting"}', NULL, false),
  ('Path 2 Green Gem', 'Gem', 'Creates a weekly action plan for high-risk and critical Gold accounts: a problem statement plus verified risk/root cause, actions completed, next action/owner/exact date, intended path to green outcome, and blocker or leadership task. Date and Guardian score are filled in by the CSM.', 'https://gemini.google.com/gem/ad55e01d49aa', '{"post-meeting"}', NULL, false),
  ('SIPP Info to TAM Handoff Gem', 'Gem', 'Builds a brief for a TAM to reference when engaging with an account. Upload a customer check-in or business review deck, call transcripts, Account Overview, and other resources (see the Gem’s instructions for the full list) to hand off context that helps the TAM support the CTA.', 'https://gemini.google.com/gem/1LfgD_tSxzFcCN_SXxd7gMPBkzctxsQku?usp=sharing', '{"closing-out"}', NULL, false),
  ('SBR Assist Gem', 'Agent', 'Helps build executive-grade Strategic Business Review decks using the Command of the Message methodology, via three stages: Intake, Apex Framing, and Slide Enhancement (slides 1–5). Access through Gemini Enterprise → Agents → "CSM SBR AI Assist"; say "Hi" to begin.', 'https://vertexaisearch.cloud.google.com/home/cid/cd50f96b-072d-4a0a-9ac3-8699ac11797f/r/agent/7944332289853326822/session/-', '{"sbr"}', NULL, false),
  ('SBR Quality Checker Gem', 'Agent', 'Evaluates an SBR deck against a built-in rubric, producing a per-slide verdict, specific recommendations, and a review checklist before the customer presentation. Say "Hi" to start.', 'https://vertexaisearch.cloud.google.com/home/cid/cd50f96b-072d-4a0a-9ac3-8699ac11797f/r/agent/9576353426048634315/session/-', '{"sbr"}', NULL, false),
  ('Gong AI Trainer', 'Gong resource', 'Practice calls and get AI-driven coaching feedback before a real customer meeting.', 'https://us-5814.app.gong.io/coaching/trainer-demo?workspace-id=5383262448296349696', '{"meeting-prep"}', NULL, false),
  ('Gong AI Assistant', 'Gong resource', 'In-call AI assistant for live meeting support.', 'https://us-5814.app.gong.io/assistant?workspace-id=5383262448296349696', '{"meeting"}', NULL, false),
  ('Gong AI Briefing Tool', 'Gong resource', 'Generates an AI briefing on an account ahead of a call.', 'https://us-5814.app.gong.io/home', '{"meeting-prep"}', NULL, false),
  ('Prepare for Upcoming Meetings', 'Gong resource', 'Gong home surface for reviewing and preparing for upcoming meetings.', 'https://us-5814.app.gong.io/home', '{"meeting-prep"}', NULL, false);
